mapper.select:
SELECT id, reservation_date AS reservationDate, reserved_by AS reservedBy, classroom_name AS classroomName, exercise_type AS exerciseType, patient_name AS patientName, gender, age, medical_record_number AS medicalRecordNumber, created_time AS createdTime, reservation_status AS reservationStatus FROM class_reservation_record
AND patient_name LIKE CONCAT('%', #{query.customerName}, '%')
AND classroom_name = #{query.classroomName}
AND reservation_status = #{query.reservationStatus}
AND reservation_date >= #{query.startDate}
AND reservation_date <= #{query.endDate}
ORDER BY reservation_date DESC
